entries.text:
`flex min-w-0 items-center gap-3 rounded-global border p-3 text-left transition-all ${
                      selectedStat
                        ? 'border-primary/55 bg-primary/10 shadow-[0_0_18px_color-mix(in_srgb,var(--color-primary)_12%,transparent)]'
                        : 'border-border-light bg-bg-card/40 hover:border-primary/30 hover:bg-bg-card-hover/60'
                    }`

`Reset to earliest arrival · currently ${formatLocalArrivalFromUnix(arriveAtUnix)} (+${offsetMinutes}m) · TT ${formatTravelDuration(entry.oneWayTTSeconds)}${
                  fireUnix != null ? ` · launch ${formatLocalArrivalFromUnix(fireUnix)}` : ''
                }`

`flex min-w-0 flex-1 items-center gap-2 rounded-lg border px-2.5 py-1.5 md:min-w-[140px] md:flex-none ${
              selectedInStock ? 'border-border-base bg-bg-card/50' : 'border-amber-500/40 bg-amber-500/5'
            }`

`shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${
					enabled
						? 'border-success/35 bg-success/10 text-success'
						: 'border-error/35 bg-error/10 text-error'
				}`

`m-0 list-none space-y-1.5 overflow-y-auto p-0 pr-1 marker:hidden [scrollbar-gutter:stable] ${
          expandToViewport ? 'min-h-0 flex-1' : 'max-h-[min(70vh,28rem)]'
        }`

`flex h-10 w-10 shrink-0 items-center justify-center rounded-global border ${
          front ? 'border-warning/40 bg-warning/12 text-warning' : 'border-primary/40 bg-primary/12 text-primary'
        }`

`rounded-full border font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 disabled:cursor-not-allowed disabled:opacity-45 ${sizeClass} ${
              active
                ? 'border-primary/45 bg-primary/12 text-primary'
                : 'border-border-base bg-bg-card/35 text-text-muted hover:text-text-main'
            }`

`m3-input w-full border px-4 py-2.5 text-text-main placeholder-text-muted focus:outline-none transition-colors duration-200 text-sm
              ${error ? 'border-error focus:border-error focus:ring-error' : 'border-border-base focus:border-primary focus:ring-primary'}
              ${leftIcon ? 'pl-10' : ''}
              ${rightIcon ? 'pr-10' : ''}
              ${className}
            `

`m3-select-trigger w-full border px-4 py-2.5 text-sm font-medium text-text-main transition-colors duration-200 flex items-center justify-between group focus:outline-none ${
          disabled
            ? 'opacity-50 cursor-not-allowed border-border-base'
            : 'border-border-base hover:border-primary focus:border-primary cursor-pointer'
        }`

`w-4 h-4 text-text-muted transition-transform duration-300 shrink-0 ${
            isOpen ? 'rotate-180 text-primary' : ''
          }`

`relative flex shrink-0 items-center justify-center rounded-global border bg-bg-card ${
        row.active
          ? 'border-primary ring-2 ring-primary/35 shadow-sm'
          : 'border-border-light border-solid'
      }`

`relative flex shrink-0 flex-col items-center justify-center gap-0.5 rounded-global border px-1 py-0.5 text-center leading-tight ${
        row.active
          ? 'border-primary ring-2 ring-primary/35 shadow-sm bg-bg-card'
          : 'border-border-light border-solid bg-bg-card'
      }`

`flex cursor-grab items-center gap-2 rounded-global border bg-bg-card px-2 py-2 transition-colors active:cursor-grabbing ${
								dragging ? 'border-primary/40 opacity-45' : targeted ? 'border-primary bg-primary/10' : 'border-border-base/50 hover:border-primary/30'
							}`

`group/item relative flex w-[5.75rem] flex-col items-center gap-2 rounded-global border bg-bg-card/70 p-3 text-center shadow-sm transition-transform hover:-translate-y-1 hover:border-primary/45 ${
              index === nextRotationIndex ? 'border-primary/70 ring-1 ring-primary/25' : 'border-border-base'
            }`

`flex min-w-0 items-center justify-between gap-4 rounded-global border px-4 py-3 transition-colors ${
                castleSettings.enabled
                  ? 'border-primary/25 bg-primary/5'
                  : 'border-border-base bg-bg-card/45'
              }`

`group rounded-global border p-4 text-left transition-colors disabled:cursor-wait disabled:opacity-70 ${
							configuredConnectionMode === 'full'
								? 'border-primary/60 bg-primary/10 ring-1 ring-primary/20'
								: 'border-border-base bg-surface-muted/30 hover:border-primary/35 hover:bg-surface-muted/60'
						}`

`group rounded-global border p-4 text-left transition-colors disabled:cursor-wait disabled:opacity-70 ${
							configuredConnectionMode === 'background'
								? 'border-primary/60 bg-primary/10 ring-1 ring-primary/20'
								: 'border-border-base bg-surface-muted/30 hover:border-primary/35 hover:bg-surface-muted/60'
						}`
